 s.getRange(col(column)+(start+i)).formulas=[['=HYPERLINK("'+dest.replaceAll('"','""')+'","'+label.replaceAll('"','""')+'")']];
 s.getRange(col(column)+(start+i)).format.font.color='#2167A6';
});}
